"""Write the reviewable inventory from the portable provider definitions."""

from __future__ import annotations

import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))

from hoshimi.core.provider_sources import SOURCE_PROVIDERS


def main() -> None:
    lines = [
        "# Provider inventory", "",
        "Source snapshots: pi `482c1381a`, pi-free `2da9909`, free-claude-code `f919f46d` (2026-10-19).", "",
        "Generated by `scripts/generate_provider_inventory.py`. Reference repositories are not runtime dependencies.", "",
        "Deduplication uses endpoint + protocol + credential types + plan. Existing native lanes and all 22 agg presets are retained.", "",
        "`native` and `agg` record an existing entry point, not live endpoint verification or complete upstream parity. `partial` has protocol gaps; `planned` is not registered yet.", "",
        "MiniMax API uses `minimax-api` to preserve the Agent service. Gemini Developer API uses `google`, separate from Code Assist `gemini`.",
        "The legacy `openai-codex` source maps to the existing `codex` account namespace. TypeSafe is classification, not chat.", "",
        "| Source | Source ID | Hoshimi ID | Endpoint | Protocol | Authentication | Plan | Catalog | Coverage | Notes |",
        "| --- | --- | --- | --- | --- | --- | --- | --- | --- | --- |",
    ]
    for definition in SOURCE_PROVIDERS:
        values = (definition.source, definition.source_id, definition.id, definition.base_url, definition.protocol,
                  ", ".join(definition.auth), definition.plan, definition.catalog, definition.coverage, definition.notes)
        lines.append("| " + " | ".join(value.replace("|", "\\|") for value in values) + " |")
    target = Path(__file__).resolve().parents[1] / "docs/provider-inventory.md"
    target.parent.mkdir(exist_ok=True)
    target.write_text("\n".join(lines) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
